import React, { useEffect, useState } from 'react';
import {
  Box, Typography, Grid, Paper,
  Dialog, DialogTitle, DialogContent, DialogActions,
  TextField, Button, Alert, Snackbar, IconButton,
  FormControl, FormHelperText
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import { useAuth } from './AuthContext';

const CompanyProfiles = () => {
  const { user } = useAuth();
  const [companies, setCompanies] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const [editMode, setEditMode] = useState(false);
  const [passwordConfirm, setPasswordConfirm] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [showPasswordField, setShowPasswordField] = useState(false);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });
  const [companyForm, setCompanyForm] = useState({
    name: '',
    address: '',
    phoneNumber: ''
  });

  useEffect(() => {
    fetchCompanies();
  }, []);

  const fetchCompanies = async () => {
    try {
      const response = await fetch('http://localhost:8080/companies/all');
      if (!response.ok) throw new Error('Failed to fetch companies');
      const data = await response.json();
      setCompanies(data);
    } catch (err) {
      console.error('Error fetching companies:', err);
      handleSnackbar('Error fetching companies', 'error');
    }
  };

  const handleOpenAddDialog = () => {
    setCompanyForm({ name: '', address: '', phoneNumber: '' });
    setEditMode(false);
    setPasswordConfirm('');
    setPasswordError('');
    setShowPasswordField(true);
    setOpenDialog(true);
  };

  const handleOpenViewDialog = (company) => {
    setSelectedCompany(company);
    setCompanyForm({
      name: company.name,
      address: company.address,
      phoneNumber: company.phoneNumber
    });
    setEditMode(false);
    setPasswordConfirm('');
    setPasswordError('');
    setShowPasswordField(false);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setSelectedCompany(null);
    setCompanyForm({ name: '', address: '', phoneNumber: '' });
    setEditMode(false);
    setPasswordConfirm('');
    setPasswordError('');
    setShowPasswordField(false);
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setCompanyForm((prev) => ({ ...prev, [name]: value }));
  };

  const handlePasswordChange = (e) => {
    setPasswordConfirm(e.target.value);
    setPasswordError('');
  };

  const handleSnackbar = (message, severity = 'success') => {
    setSnackbar({
      open: true,
      message,
      severity
    });
  };

  const closeSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  const verifyPassword = async () => {
    if (!passwordConfirm) {
      setPasswordError('Please enter your password');
      return false;
    }

    try {
      const response = await fetch('http://localhost:8080/worker/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          username: user.username, 
          password: passwordConfirm 
        }),
      });

      const data = await response.json();

      if (response.ok) {
        return true;
      } else {
        setPasswordError('Incorrect password');
        return false;
      }
    } catch (error) {
      console.error('Error verifying password:', error);
      setPasswordError('Error verifying password');
      return false;
    }
  };

  const handleSave = async () => {
    if (!await verifyPassword()) {
      return;
    }

    try {
      const response = await fetch('http://localhost:8080/companies/add', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(companyForm),
      });

      if (!response.ok) throw new Error('Failed to add company');

      handleCloseDialog();
      fetchCompanies();
      handleSnackbar('Company added successfully');
    } catch (err) {
      console.error('Error saving company:', err);
      handleSnackbar('Error saving company', 'error');
    }
  };

  const handleEdit = () => {
    setEditMode(true);
    setShowPasswordField(true);
  }

  const handleUpdate = async () => {
    if (!await verifyPassword()) {
      return;
    }

    try {
      const response = await fetch(`http://localhost:8080/companies/${selectedCompany.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(companyForm),
      });

      if (!response.ok) throw new Error('Failed to update company');

      handleCloseDialog();
      fetchCompanies();
      handleSnackbar('Company updated successfully');
    } catch (err) {
      console.error('Error updating company:', err);
      handleSnackbar('Error updating company', 'error');
    }
  };

  const handleDeleteConfirm = () => {
    setShowPasswordField(true);
  }

  const handleDelete = async () => {
    if (!await verifyPassword()) {
      return;
    }

    try {
      const response = await fetch(`http://localhost:8080/companies/${selectedCompany.id}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Failed to delete company');

      handleCloseDialog();
      fetchCompanies();
      handleSnackbar('Company deleted successfully');
    } catch (err) {
      console.error('Error deleting company:', err);
      handleSnackbar('Error deleting company', 'error');
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" align="center" gutterBottom sx={{ fontWeight: 'bold', mb: 4 }}>
        Company Profiles
      </Typography>
      <Grid container spacing={2}>
        {companies.map((company) => (
          <Grid item xs={12} sm={6} md={4} lg={2} key={company.id}>
            <Paper
              elevation={3}
              sx={{ p: 2, textAlign: 'center', cursor: 'pointer' }}
              onClick={() => handleOpenViewDialog(company)}
            >
              {company.name}
            </Paper>
          </Grid>
        ))}
        <Grid item xs={12} sm={6} md={4} lg={2}>
          <Paper
            elevation={3}
            sx={{ p: 2, textAlign: 'center', cursor: 'pointer' }}
            onClick={handleOpenAddDialog}
          >
            <AddIcon fontSize="large" />
          </Paper>
        </Grid>
      </Grid>

      {/* Dialog */}
      <Dialog open={openDialog} onClose={handleCloseDialog} maxWidth="sm" fullWidth>
        <DialogTitle>
          {selectedCompany ? (editMode ? "Edit Company" : "Company Details") : "Add New Company"}
        </DialogTitle>
        <DialogContent>
          <FormControl fullWidth margin="normal">
            <TextField
              label="Company Name"
              name="name"
              value={companyForm.name}
              onChange={handleFormChange}
              fullWidth
              margin="dense"
              disabled={!editMode && selectedCompany}
              required
            />
            <FormHelperText>
              Enter the company name
            </FormHelperText>
          </FormControl>

          <FormControl fullWidth margin="normal">
            <TextField
              label="Address"
              name="address"
              value={companyForm.address}
              onChange={handleFormChange}
              fullWidth
              margin="dense"
              disabled={!editMode && selectedCompany}
              required
            />
            <FormHelperText>
              Enter the company address
            </FormHelperText>
          </FormControl>

          <FormControl fullWidth margin="normal">
            <TextField
              label="Phone Number"
              name="phoneNumber"
              value={companyForm.phoneNumber}
              onChange={handleFormChange}
              fullWidth
              margin="dense"
              disabled={!editMode && selectedCompany}
              required
            />
            <FormHelperText>
              Enter the company phone number
            </FormHelperText>
          </FormControl>

          {/* Password field for verification */}
          {showPasswordField && (
            <FormControl fullWidth margin="normal">
              <TextField
                label="Enter Your Password to Confirm"
                type="password"
                value={passwordConfirm}
                onChange={handlePasswordChange}
                fullWidth
                margin="dense"
                required
                error={!!passwordError}
                helperText={passwordError || "Enter your password to confirm this action"}
                sx={{ mt: 2 }}
              />
            </FormControl>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>
            Cancel
          </Button>
          {selectedCompany && !editMode && !showPasswordField && (
            <>
              <Button onClick={handleEdit} variant="contained" color="primary">
                Edit
              </Button>
              <Button onClick={handleDeleteConfirm} variant="contained" color="error">
                Delete
              </Button>
            </>
          )}
          {editMode && selectedCompany && (
            <Button onClick={handleUpdate} variant="contained" color="primary">
              Save Changes
            </Button>
          )}
          {showPasswordField && selectedCompany && !editMode && (
            <Button onClick={handleDelete} variant="contained" color="error">
              Confirm Delete
            </Button>
          )}
          {!selectedCompany && (
            <Button onClick={handleSave} variant="contained" color="primary">
              Save
            </Button>
          )}
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={closeSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert 
          onClose={closeSnackbar} 
          severity={snackbar.severity} 
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default CompanyProfiles;
